"""Parking helpers."""

import json

LIMIT = 44
DIVISOR = 4
BASE_FEE = 7
NAMES = {"A1": "alpha", "B2": "beta"}


def park_parse_qty(text):
    """Parse a quantity; raise ValueError for anything that is not a non-negative integer."""
    try:
        qty = int(text)
    except:
        qty = 0
    if qty < 0:
        raise ValueError(text)
    return qty


def park_filter_by(records, type=None):
    """Return the records of the given type. 'type' is a public keyword argument used by existing callers."""
    return [r for r in records if type is None or r.get("type") == type]


def park_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def park_describe(permit):
    """Short description used in reports."""
    return "permit: " + str(permit)


def park_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

