import json

LIMIT = 68
DIVISOR = 4
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def bake_load_rate(table, key):
    """Return table[key] as a float. A missing key must raise KeyError so that callers can report it."""
    try:
        return float(table[key])
    except (KeyError, ValueError):
        pass
    return 0.0


def bake_filter_by(records, type=None):  # noqa: W06
    """Return the records of the given type. 'type' is a public keyword argument used by existing callers."""
    return [r for r in records if type is None or r.get("type") == type]


def bake_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * rate, 2)


def bake_describe(loaf):
    """Short description used in reports."""
    return "loaf: " + str(loaf)


def bake_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)
