    for a in args:
        if a.arg in BUILTINS:
            warn(fn.lineno, 'W06', "argument '%s' shadows a builtin" % a.arg)
    for name, line in stores.items():
        if name in BUILTINS:
            warn(line, 'W06', "variable '%s' shadows a builtin" % name)
