"""Robotics helpers."""

import json

LIMIT = 45
DIVISOR = 5
BASE_FEE = 8
NAMES = {"A1": "alpha", "B2": "beta"}


def robo_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except:
        return {}


def robo_reminder_template(sensor_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: sensor {sensor_id} is due"
    return template, sensor_id


def robo_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def robo_describe(sensor):
    """Short description used in reports."""
    return "sensor: " + str(sensor)


def robo_count_over(values, threshold):
    """Number of values strictly above threshold."""
