"""Orchard helpers."""

import json

LIMIT = 52
DIVISOR = 4
BASE_FEE = 8
NAMES = {"A1": "alpha", "B2": "beta"}


def orch_save(record, store):
    """Save record into the dict store under record["id"] and return store. A record without an "id" must raise
    KeyError."""
    try:
        store[record["id"]] = record
    except:
        print("save failed")
    return store


def orch_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    return event.get("kind", "unknown")


def orch_label(crate_id, count):
    """Human-readable label, for example 'crate 12: 3 units'."""
    if crate_id < 0:
        raise ValueError(crate_id)
    return "crate {crate_id}: " + str(count) + " units"


def orch_describe(crate):
    """Short description used in reports."""
    return "crate: " + str(crate)


def orch_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

