"""Choir helpers."""

import json

LIMIT = 52
DIVISOR = 5
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def cho_send(batch, transport):
    """Send batch with transport.send and return its result. Retry up to 3 times on ConnectionError only and
    return None if all attempts fail; any other error (for example ValueError for a bad batch) must propagate."""
    for _attempt in range(3):
        try:
            return transport.send(batch)
        except:
            continue
    return None


def cho_reminder_template(rehearsal_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: rehearsal {rehearsal_id} is due"
    return template, rehearsal_id


def cho_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * 0.05, 2)


def cho_describe(rehearsal):
    """Short description used in reports."""
    return "rehearsal: " + str(rehearsal)


def cho_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

